let icn = 0;
// Inline <svg> shares one document-wide id namespace, so give every instance's gradient ids a unique suffix.
const uniq = (body) => { const n = ++icn; return body.replace(/\bid="([A-Za-z0-9_]+)"/g, (_, i) => `id="${i}_${n}"`).replace(/url\(#([A-Za-z0-9_]+)\)/g, (_, i) => `url(#${i}_${n})`); };
export const iconSvg = (name, size = 24) => `<svg class="ic2" width="${size}" height="${size}" viewBox="0 0 100 100" aria-hidden="true">${uniq(ICONS[name] || '')}</svg>`;
export const iconUrl = (name) => 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">${ICONS[name] || ''}</svg>`);
const iconImgs = new Map();
export const iconImg = (name) => { if (!iconImgs.has(name)) { const im = new Image(); im.src = iconUrl(name); iconImgs.set(name, im); } return iconImgs.get(name); };
